1	// Query-string rewriting for matched routes: queryTransforms are applied
2	// after route selection and never touch path matching or joining. The
3	// rewriter works on raw fragments so unmodified parameters (including
4	// duplicates, empty values and empty fragments) keep their original bytes
5	// and relative order; only a rule's target parameter is decoded for name
6	// comparison and re-encoded when set, renamed or copied.
7	package contractsentinel
8	
9	import "strings"
10	
11	// queryItem is one '&'-separated fragment of a query string in its current
12	// order. Empty fragments ("" between separators) are retained but never
13	// match a parameter name.
14	type queryItem struct {
15		empty bool   // an empty fragment, kept verbatim but not a parameter
16		name  string // decoded parameter name (only meaningful when !empty)
17		raw   string // original fragment text, or the encoded pair after a set
18	}
19	
20	// applyQueryTransforms parses the raw query of target (the text after the
21	// first '?') and applies the route's transforms in array order. It returns
22	// the full query suffix including a leading '?', or "" when the final
23	// result has no query string.
24	func applyQueryTransforms(transforms []*QueryTransform, target string) (string, *Failure) {
25		i := strings.IndexByte(target, '?')
26		if len(transforms) == 0 {
27			// No rules: the original query is preserved byte for byte.
28			if i < 0 {
29				return "", nil
30			}
31			return target[i:], nil
32		}
33	
34		var items []queryItem
35		present := false
36		if i >= 0 {
37			present = true
38			raw := target[i+1:]
39			// An empty query string ("?") has no fragments at all; every other
40			// empty fragment (e.g. from "?&" or "?a=1&") is retained as such.
41			if raw != "" {
42				for _, frag := range strings.Split(raw, "&") {
43					if frag == "" {
44						items = append(items, queryItem{empty: true})
45						continue
46					}
47					namePart := frag
48					if j := strings.IndexByte(frag, '='); j >= 0 {
49						namePart = frag[:j] // the first '=' splits name and value
50					}
51					name, ok := decodeQueryName(namePart)
52					if !ok {
53						// ParseRequest validates the whole target, so this is a
54						// belt-and-braces guard.
55						return "", failuref("invalid_request", "target contains an invalid percent escape")
56					}
57					items = append(items, queryItem{name: name, raw: frag})
58				}
59			}
60		}
61	
62		for _, tr := range transforms {
63			switch tr.Op {
64			case "remove":
65				present, items = applyRemove(items, present, tr.Name)
66			case "set":
67				present, items = applySet(items, present, tr.Name, tr.Value)
68			case "rename":
69				items = applyRename(items, tr.Name, tr.To)
70			case "copy":
71				items = applyCopy(items, tr.Name, tr.To)
72			}
73		}
74	
75		if !present {
76			return "", nil
77		}
78		parts := make([]string, len(items))
79		for k, it := range items {
80			parts[k] = it.raw
81		}
82		return "?" + strings.Join(parts, "&"), nil
83	}
84	
85	// matchesName is the one shared parameter-matching rule: an item is a hit
86	// when it is a parameter (not an empty fragment) whose decoded name equals
87	// name. Name decoding itself happens once at parse time, so every op compares
88	// the same decoded, case-sensitive form.
89	func matchesName(it queryItem, name string) bool {
90		return !it.empty && it.name == name
91	}
92	
93	// firstNameHit returns the index of the first parameter matching name, or -1
94	// when no parameter carries that name.
95	func firstNameHit(items []queryItem, name string) int {
96		for k := range items {
97			if matchesName(items[k], name) {
98				return k
99			}
100		}
101		return -1
102	}
103	
104	// dropName is the one shared keep-the-rest rule: it compacts items in place,
105	// removing every parameter matching name while empty fragments and all other
106	// parameters keep their relative order and original bytes.
107	func dropName(items []queryItem, name string) []queryItem {
108		kept := items[:0]
109		for _, it := range items {
110			if !matchesName(it, name) {
111				kept = append(kept, it)
112			}
113		}
114		return kept
115	}
116	
117	// applyRemove deletes every parameter whose decoded name equals name. With
118	// no hit the query is untouched; after a hit the '?' is dropped only when no
119	// parameters or empty fragments remain.
120	func applyRemove(items []queryItem, present bool, name string) (bool, []queryItem) {
121		if firstNameHit(items, name) < 0 {
122			return present, items
123		}
124		kept := dropName(items, name)
125		if len(kept) == 0 {
126			return false, kept
127		}
128		return true, kept
129	}
130	
131	// applySet merges all parameters with the decoded name into one encoded
132	// name=value pair at the first hit's position; a name that is absent is
133	// appended to the end and creates a query string when none existed.
134	func applySet(items []queryItem, present bool, name, value string) (bool, []queryItem) {
135		encoded := encodeQueryComponent(name) + "=" + encodeQueryComponent(value)
136		first := firstNameHit(items, name)
137		if first < 0 {
138			items = append(items, queryItem{name: name, raw: encoded})
139			return true, items
140		}
141		// The merged pair takes the first hit's place; every later duplicate is
142		// dropped by the same keep-the-rest rule remove uses.
143		items[first].raw = encoded
144		return true, append(items[:first+1], dropName(items[first+1:], name)...)
145	}
146	
147	// applyRename renames in place every parameter whose decoded name equals
148	// name: its name is re-encoded as to while the '=' (if any) and the raw
149	// value bytes after it are kept verbatim. Parameters already named to,
150	// empty fragments and non-matching parameters are untouched; when nothing
151	// matches (or name and to are identical) every fragment keeps its bytes.
152	func applyRename(items []queryItem, name, to string) []queryItem {
153		if name == to {
154			// Renaming to the same name must not re-encode existing names.
155			return items
156		}
157		encodedTo := encodeQueryComponent(to)
158		for k := range items {
159			if !matchesName(items[k], name) {
160				continue
161			}
162			frag := items[k].raw
163			if j := strings.IndexByte(frag, '='); j >= 0 {
164				// Keep the '=' and everything after it byte for byte.
165				frag = encodedTo + frag[j:]
166			} else {
167				frag = encodedTo
168			}
169			items[k].raw = frag
170			items[k].name = to
171		}
172		return items
173	}
174	
175	// applyCopy duplicates every parameter whose decoded name equals name: each
176	// copy takes the new name to (encoded the way set encodes a name) and keeps
177	// the source's '=' (if any) and raw value bytes verbatim, so a valueless
178	// parameter gains a valueless copy and an empty value keeps its '='. The
179	// source parameter stays in place and its copy is inserted immediately after
180	// it; parameters already named to, empty fragments and non-matching
181	// parameters are untouched and never merged with or overwritten by the
182	// copies. When nothing matches (or name and to are identical) every fragment
183	// keeps its bytes, no copy is made and no existing name is re-encoded; with
184	// no query string none is created, and an empty question mark survives.
185	func applyCopy(items []queryItem, name, to string) []queryItem {
186		if name == to {
187			// Copying onto the same name must not duplicate or re-encode.
188			return items
189		}
190		encodedTo := encodeQueryComponent(to)
191		out := make([]queryItem, 0, len(items))
192		for _, it := range items {
193			out = append(out, it)
194			if !matchesName(it, name) {
195				continue
196			}
197			frag := it.raw
198			if j := strings.IndexByte(frag, '='); j >= 0 {
199				// Keep the '=' and everything after it byte for byte.
200				frag = encodedTo + frag[j:]
201			} else {
202				frag = encodedTo
203			}
204			out = append(out, queryItem{name: to, raw: frag})
205		}
206		return out
207	}
208	
209	// decodeQueryName percent-decodes a raw parameter name with '+' treated as a
210	// space, as application/x-www-form-urlencoded does. Matching is
211	// case-sensitive and applies no other normalization. The bool reports
212	// whether every percent escape was well-formed.
213	func decodeQueryName(s string) (string, bool) {
214		var b strings.Builder
215		for i := 0; i < len(s); i++ {
216			switch s[i] {
217			case '+':
218				b.WriteByte(' ')
219			case '%':
220				if i+2 >= len(s) || !isHex(s[i+1]) || !isHex(s[i+2]) {
221					return "", false
222				}
223				b.WriteByte(unhex(s[i+1])<<4 | unhex(s[i+2]))
224				i += 2
225			default:
226				b.WriteByte(s[i])
227			}
228		}
229		return b.String(), true
230	}
231	
232	// encodeQueryComponent renders a literal name or value as query text: ASCII
233	// letters, digits and -._~ stay as-is, every other byte (including spaces
234	// and the individual bytes of multi-byte UTF-8 sequences) becomes an
235	// uppercase percent escape.
236	func encodeQueryComponent(s string) string {
237		var b strings.Builder
238		for i := 0; i < len(s); i++ {
239			c := s[i]
240			if isUnreserved(c) {
241				b.WriteByte(c)
242			} else {
243				b.WriteByte('%')
244				b.WriteByte(hexDigit(c >> 4))
245				b.WriteByte(hexDigit(c & 0x0f))
246			}
247		}
248		return b.String()
249	}
250	
251	func isUnreserved(c byte) bool {
252		switch {
253		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
254			return true
255		}
256		switch c {
257		case '-', '.', '_', '~':
258			return true
259		}
260		return false
261	}
262	
263	func unhex(c byte) byte {
264		switch {
265		case c >= '0' && c <= '9':
266			return c - '0'
267		case c >= 'a' && c <= 'f':
268			return c - 'a' + 10
269		default:
270			return c - 'A' + 10
271		}
272	}
273	
274	func hexDigit(n byte) byte {
275		const digits = "0123456789ABCDEF"
276		return digits[n]
277	}
