// Query-string rewriting for matched routes: queryTransforms are applied
// after route selection and never touch path matching or joining. The
// rewriter works on raw fragments so unmodified parameters (including
// duplicates, empty values and empty fragments) keep their original bytes
// and relative order; only a rule's target parameter is decoded for name
// comparison and re-encoded when set, renamed or copied.
package contractsentinel

import "strings"

// queryItem is one '&'-separated fragment of a query string in its current
// order. Empty fragments ("" between separators) are retained but never
// match a parameter name.
type queryItem struct {
	empty bool   // an empty fragment, kept verbatim but not a parameter
	name  string // decoded parameter name (only meaningful when !empty)
	raw   string // original fragment text, or the encoded pair after a set
}

// applyQueryTransforms parses the raw query of target (the text after the
// first '?') and applies the route's transforms in array order. It returns
// the full query suffix including a leading '?', or "" when the final
// result has no query string.
func applyQueryTransforms(transforms []*QueryTransform, target string) (string, *Failure) {
	i := strings.IndexByte(target, '?')
	if len(transforms) == 0 {
		// No rules: the original query is preserved byte for byte.
		if i < 0 {
			return "", nil
		}
		return target[i:], nil
	}

	var items []queryItem
	present := false
	if i >= 0 {
		present = true
		raw := target[i+1:]
		// An empty query string ("?") has no fragments at all; every other
		// empty fragment (e.g. from "?&" or "?a=1&") is retained as such.
		if raw != "" {
			for _, frag := range strings.Split(raw, "&") {
				if frag == "" {
					items = append(items, queryItem{empty: true})
					continue
				}
				namePart := frag
				if j := strings.IndexByte(frag, '='); j >= 0 {
					namePart = frag[:j] // the first '=' splits name and value
				}
				name, ok := decodeQueryName(namePart)
				if !ok {
					// ParseRequest validates the whole target, so this is a
					// belt-and-braces guard.
					return "", failuref("invalid_request", "target contains an invalid percent escape")
				}
				items = append(items, queryItem{name: name, raw: frag})
			}
		}
	}

	for _, tr := range transforms {
		switch tr.Op {
		case "remove":
			present, items = applyRemove(items, present, tr.Name)
		case "set":
			present, items = applySet(items, present, tr.Name, tr.Value)
		case "rename":
			items = applyRename(items, tr.Name, tr.To)
		case "copy":
			items = applyCopy(items, tr.Name, tr.To)
		}
	}

	if !present {
		return "", nil
	}
	parts := make([]string, len(items))
	for k, it := range items {
		parts[k] = it.raw
	}
	return "?" + strings.Join(parts, "&"), nil
}

// matchesName is the one shared parameter-matching rule: an item is a hit
// when it is a parameter (not an empty fragment) whose decoded name equals
// name. Name decoding itself happens once at parse time, so every op compares
// the same decoded, case-sensitive form.
func matchesName(it queryItem, name string) bool {
	return !it.empty && it.name == name
}

// firstNameHit returns the index of the first parameter matching name, or -1
// when no parameter carries that name.
func firstNameHit(items []queryItem, name string) int {
	for k := range items {
		if matchesName(items[k], name) {
			return k
		}
	}
	return -1
}

// dropName is the one shared keep-the-rest rule: it compacts items in place,
// removing every parameter matching name while empty fragments and all other
// parameters keep their relative order and original bytes.
func dropName(items []queryItem, name string) []queryItem {
	kept := items[:0]
	for _, it := range items {
		if !matchesName(it, name) {
			kept = append(kept, it)
		}
	}
	return kept
}

// applyRemove deletes every parameter whose decoded name equals name. With
// no hit the query is untouched; after a hit the '?' is dropped only when no
// parameters or empty fragments remain.
func applyRemove(items []queryItem, present bool, name string) (bool, []queryItem) {
	if firstNameHit(items, name) < 0 {
		return present, items
	}
	kept := dropName(items, name)
	if len(kept) == 0 {
		return false, kept
	}
	return true, kept
}

// applySet merges all parameters with the decoded name into one encoded
// name=value pair at the first hit's position; a name that is absent is
// appended to the end and creates a query string when none existed.
func applySet(items []queryItem, present bool, name, value string) (bool, []queryItem) {
	encoded := encodeQueryComponent(name) + "=" + encodeQueryComponent(value)
	first := firstNameHit(items, name)
	if first < 0 {
		items = append(items, queryItem{name: name, raw: encoded})
		return true, items
	}
	// The merged pair takes the first hit's place; every later duplicate is
	// dropped by the same keep-the-rest rule remove uses.
	items[first].raw = encoded
	return true, append(items[:first+1], dropName(items[first+1:], name)...)
}

// applyRename renames in place every parameter whose decoded name equals
// name: its name is re-encoded as to while the '=' (if any) and the raw
// value bytes after it are kept verbatim. Parameters already named to,
// empty fragments and non-matching parameters are untouched; when nothing
// matches (or name and to are identical) every fragment keeps its bytes.
func applyRename(items []queryItem, name, to string) []queryItem {
	if name == to {
		// Renaming to the same name must not re-encode existing names.
		return items
	}
	encodedTo := encodeQueryComponent(to)
	for k := range items {
		if !matchesName(items[k], name) {
			continue
		}
		frag := items[k].raw
		if j := strings.IndexByte(frag, '='); j >= 0 {
			// Keep the '=' and everything after it byte for byte.
			frag = encodedTo + frag[j:]
		} else {
			frag = encodedTo
		}
		items[k].raw = frag
		items[k].name = to
	}
	return items
}

// applyCopy duplicates every parameter whose decoded name equals name: each
// copy takes the new name to (encoded the way set encodes a name) and keeps
// the source's '=' (if any) and raw value bytes verbatim, so a valueless
// parameter gains a valueless copy and an empty value keeps its '='. The
// source parameter stays in place and its copy is inserted immediately after
// it; parameters already named to, empty fragments and non-matching
// parameters are untouched and never merged with or overwritten by the
// copies. When nothing matches (or name and to are identical) every fragment
// keeps its bytes, no copy is made and no existing name is re-encoded; with
// no query string none is created, and an empty question mark survives.
func applyCopy(items []queryItem, name, to string) []queryItem {
	if name == to {
		// Copying onto the same name must not duplicate or re-encode.
		return items
	}
	encodedTo := encodeQueryComponent(to)
	out := make([]queryItem, 0, len(items))
	for _, it := range items {
		out = append(out, it)
		if !matchesName(it, name) {
			continue
		}
		frag := it.raw
		if j := strings.IndexByte(frag, '='); j >= 0 {
			// Keep the '=' and everything after it byte for byte.
			frag = encodedTo + frag[j:]
		} else {
			frag = encodedTo
		}
		out = append(out, queryItem{name: to, raw: frag})
	}
	return out
}

// decodeQueryName percent-decodes a raw parameter name with '+' treated as a
// space, as application/x-www-form-urlencoded does. Matching is
// case-sensitive and applies no other normalization. The bool reports
// whether every percent escape was well-formed.
func decodeQueryName(s string) (string, bool) {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '+':
			b.WriteByte(' ')
		case '%':
			if i+2 >= len(s) || !isHex(s[i+1]) || !isHex(s[i+2]) {
				return "", false
			}
			b.WriteByte(unhex(s[i+1])<<4 | unhex(s[i+2]))
			i += 2
		default:
			b.WriteByte(s[i])
		}
	}
	return b.String(), true
}

// encodeQueryComponent renders a literal name or value as query text: ASCII
// letters, digits and -._~ stay as-is, every other byte (including spaces
// and the individual bytes of multi-byte UTF-8 sequences) becomes an
// uppercase percent escape.
func encodeQueryComponent(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if isUnreserved(c) {
			b.WriteByte(c)
		} else {
			b.WriteByte('%')
			b.WriteByte(hexDigit(c >> 4))
			b.WriteByte(hexDigit(c & 0x0f))
		}
	}
	return b.String()
}

func isUnreserved(c byte) bool {
	switch {
	case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
		return true
	}
	switch c {
	case '-', '.', '_', '~':
		return true
	}
	return false
}

func unhex(c byte) byte {
	switch {
	case c >= '0' && c <= '9':
		return c - '0'
	case c >= 'a' && c <= 'f':
		return c - 'a' + 10
	default:
		return c - 'A' + 10
	}
}

func hexDigit(n byte) byte {
	const digits = "0123456789ABCDEF"
	return digits[n]
}

package contractsentinel

import (
	"strings"
	"testing"
)

func TestQueryTransformCopySpecExample(t *testing.T) {
	// old=%2f+&new=9&old, copy old -> new: every copy follows its source, the
	// existing new=9 stays put, and the valueless old gains a valueless copy.
	rules := `[{"op":"copy","name":"old","to":"new"}]`
	got := transformResult(t, rules, "/p?old=%2f+&new=9&old")
	want := "http://h.internal/base/p?old=%2f+&new=%2f+&new=9&old&new"
	if got != want {
		t.Fatalf("upstreamURL = %q, want %q", got, want)
	}
}

func TestQueryTransformCopy(t *testing.T) {
	cases := []struct {
		name      string
		rules     string
		target    string
		wantQuery string // expected suffix after http://h.internal/base/p
	}{
		{
			name:      "copy every hit, each copy right after its source",
			rules:     `[{"op":"copy","name":"old","to":"new"}]`,
			target:    "/p?old=1&b=2&old=3",
			wantQuery: "?old=1&new=1&b=2&old=3&new=3",
		},
		{
			name:      "copy keeps existing target parameters without merging",
			rules:     `[{"op":"copy","name":"old","to":"new"}]`,
			target:    "/p?new=9&old=1&new=8",
			wantQuery: "?new=9&old=1&new=1&new=8",
		},
		{
			name:      "copy matches percent-decoded source names",
			rules:     `[{"op":"copy","name":"old","to":"new"}]`,
			target:    "/p?%6Fld=1",
			wantQuery: "?%6Fld=1&new=1",
		},
		{
			name:      "copy matches plus-as-space source names",
			rules:     `[{"op":"copy","name":"a b","to":"c d"}]`,
			target:    "/p?a+b=1",
			wantQuery: "?a+b=1&c%20d=1",
		},
		{
			name:      "copy is case sensitive",
			rules:     `[{"op":"copy","name":"old","to":"new"}]`,
			target:    "/p?OLD=1&old=2",
			wantQuery: "?OLD=1&old=2&new=2",
		},
		{
			name:      "copy of a valueless parameter is valueless",
			rules:     `[{"op":"copy","name":"old","to":"new"}]`,
			target:    "/p?old&x=1",
			wantQuery: "?old&new&x=1",
		},
		{
			name:      "copy keeps an empty value's equals sign",
			rules:     `[{"op":"copy","name":"old","to":"new"}]`,
			target:    "/p?old=&x=1",
			wantQuery: "?old=&new=&x=1",
		},
		{
			name:      "copy preserves value bytes verbatim",
			rules:     `[{"op":"copy","name":"old","to":"new"}]`,
			target:    "/p?old=%2f+%2F+a=b&x",
			wantQuery: "?old=%2f+%2F+a=b&new=%2f+%2F+a=b&x",
		},
		{
			name:      "copy encodes the new name like set",
			rules:     `[{"op":"copy","name":"old","to":"n ew/x"}]`,
			target:    "/p?old=1",
			wantQuery: "?old=1&n%20ew%2Fx=1",
		},
		{
			name:      "copy leaves non-hit fragments and empty fragments as is",
			rules:     `[{"op":"copy","name":"old","to":"new"}]`,
			target:    "/p?a=1&&old=2&&",
			wantQuery: "?a=1&&old=2&new=2&&",
		},
		{
			name:      "copy with no hit changes nothing byte for byte",
			rules:     `[{"op":"copy","name":"old","to":"new"}]`,
			target:    "/p?a=1&%62=2",
			wantQuery: "?a=1&%62=2",
		},
		{
			name:      "copy with no query string does not create a mark",
			rules:     `[{"op":"copy","name":"old","to":"new"}]`,
			target:    "/p",
			wantQuery: "",
		},
		{
			name:      "copy with no hit keeps an empty question mark",
			rules:     `[{"op":"copy","name":"old","to":"new"}]`,
			target:    "/p?",
			wantQuery: "?",
		},
		{
			name:      "copy after a hit keeps an empty question mark with empties",
			rules:     `[{"op":"copy","name":"old","to":"new"}]`,
			target:    "/p?old=1&",
			wantQuery: "?old=1&new=1&",
		},
		{
			name:      "copy to the same name neither duplicates nor re-encodes",
			rules:     `[{"op":"copy","name":"a b","to":"a b"}]`,
			target:    "/p?a+b=1&a%20b=2",
			wantQuery: "?a+b=1&a%20b=2",
		},
		{
			name:      "copy chains: later remove of the source keeps the copies",
			rules:     `[{"op":"copy","name":"old","to":"new"},{"op":"remove","name":"old"}]`,
			target:    "/p?old=1&x=3&old=2",
			wantQuery: "?new=1&x=3&new=2",
		},
		{
			name:      "copy chains: later set on the target merges copies and originals",
			rules:     `[{"op":"copy","name":"old","to":"new"},{"op":"set","name":"new","value":"z"}]`,
			target:    "/p?new=1&old=2",
			wantQuery: "?new=z&old=2",
		},
		{
			name:      "copy chains: later rename moves only the copies",
			rules:     `[{"op":"copy","name":"old","to":"new"},{"op":"rename","name":"new","to":"n2"}]`,
			target:    "/p?old=1",
			wantQuery: "?old=1&n2=1",
		},
		{
			name:      "copy after rename duplicates the renamed parameters",
			rules:     `[{"op":"rename","name":"a","to":"old"},{"op":"copy","name":"old","to":"new"}]`,
			target:    "/p?a=1",
			wantQuery: "?old=1&new=1",
		},
		{
			name:      "copy of a copy walks the chain",
			rules:     `[{"op":"copy","name":"a","to":"b"},{"op":"copy","name":"b","to":"c"}]`,
			target:    "/p?a=1",
			wantQuery: "?a=1&b=1&c=1",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := transformResult(t, tc.rules, tc.target)
			want := buildWant(tc.target, tc.wantQuery)
			if got != want {
				t.Errorf("upstreamURL = %q, want %q", got, want)
			}
		})
	}
}

// TestQueryTransformCopySpecialNames covers the name-comparison rules across
// a copy: a literal '+' or space in the rule's to is encoded like set, and
// the source name keeps matching decoded, case-sensitive request names.
func TestQueryTransformCopySpecialNames(t *testing.T) {
	cases := []struct {
		name      string
		rules     string
		target    string
		wantQuery string
	}{
		{
			// The literal name "a+b" matches only the encoded-plus form; the
			// space spellings ('+' and "%20") are different parameters.
			name:      "literal plus source matches encoded plus only",
			rules:     `[{"op":"copy","name":"a+b","to":"c"}]`,
			target:    "/p?a+b=1&a%2Bb=2&a%20b=3",
			wantQuery: "?a+b=1&a%2Bb=2&c=2&a%20b=3",
		},
		{
			// A space in the copy name is encoded %20, and the copy lands
			// after its source while the encoded-plus parameter is untouched.
			name:      "space copy name is encoded and source stays raw",
			rules:     `[{"op":"copy","name":"a","to":"x y"}]`,
			target:    "/p?a=1&x%2By=2",
			wantQuery: "?a=1&x%20y=1&x%2By=2",
		},
		{
			// Non-ASCII copy name: encoded like set, byte by byte.
			name:      "chinese copy name is encoded",
			rules:     `[{"op":"copy","name":"a","to":"中 文"}]`,
			target:    "/p?a=1",
			wantQuery: "?a=1&%E4%B8%AD%20%E6%96%87=1",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := transformResult(t, tc.rules, tc.target)
			want := buildWant(tc.target, tc.wantQuery)
			if got != want {
				t.Errorf("upstreamURL = %q, want %q", got, want)
			}
		})
	}
}

// TestQueryTransformCopyOnlyAppliedAfterMatching pins that copy rules are
// query content only: they run after route selection, so a copy on a losing
// route is not executed and matching, conflict resolution and path joining
// are exactly what they are without rules.
func TestQueryTransformCopyOnlyAppliedAfterMatching(t *testing.T) {
	cfg := mustConfig(t, `{"routes":[
	  {"id":"wide","methods":["*"],"pathPrefix":"/x","upstream":"http://w",
	   "queryTransforms":[{"op":"copy","name":"a","to":"from"}]},
	  {"id":"get","methods":["GET"],"pathPrefix":"/x","upstream":"http://g",
	   "queryTransforms":[{"op":"copy","name":"a","to":"to"}]}
	]}`)
	res := resolveJSON(t, cfg, `{"method":"GET","target":"/x/1?a=1"}`)
	if res.RouteID != "get" || res.UpstreamURL != "http://g/1?a=1&to=1" {
		t.Fatalf("got %+v", res)
	}

	// The wildcard route's copy applies when it wins instead.
	res = resolveJSON(t, cfg, `{"method":"POST","target":"/x/1?a=1"}`)
	if res.RouteID != "wide" || res.UpstreamURL != "http://w/1?a=1&from=1" {
		t.Fatalf("got %+v", res)
	}
}

// TestQueryTransformCopyInvalidEscapeStillRejected pins that a copy rule can
// never launder a malformed percent escape into an accepted request: all
// names are decoded before any rule runs, so copying the carrying parameter
// cannot make the request valid.
func TestQueryTransformCopyInvalidEscapeStillRejected(t *testing.T) {
	cfg := transformConfig(t, `[{"op":"copy","name":"a","to":"b"}]`)
	for _, target := range []string{"/p?a=1&b%zz=2", "/p?a%zz=1"} {
		_, rf := ParseRequest([]byte(`{"method":"GET","target":"` + target + `"}`))
		if rf == nil || rf.Code != "invalid_request" {
			t.Fatalf("ParseRequest(%q): got %+v, want invalid_request", target, rf)
		}
		res, rf := Resolve(cfg, &Request{Method: "GET", Target: target})
		if rf == nil || rf.Code != "invalid_request" {
			t.Fatalf("Resolve(%q): got %+v, want invalid_request", target, rf)
		}
		if res != nil {
			t.Fatalf("Resolve(%q): got partial success %+v, want no resolution", target, res)
		}
	}
}

// TestQueryTransformCopyRoundTrip saves a config carrying copy rules through
// the existing JSON save support and re-reads it: the copy fields, literal
// names and rule order survive, and the same request resolves identically.
func TestQueryTransformCopyRoundTrip(t *testing.T) {
	cfg := mustConfig(t, `{"routes":[{"id":"r1","methods":["*"],"pathPrefix":"/","upstream":"http://h.internal/base",
	  "queryTransforms":[
	    {"op":"copy","name":"old","to":"中 文+"},
	    {"op":"copy","name":"a b","to":"c d"},
	    {"op":"remove","name":"old"}
	  ]}]}`)

	// The saved document keeps the copy rules in order with their literal
	// names and to fields, and copy never gains a value field.
	doc := string(mustMarshal(t, cfg))
	wantSequence := `"queryTransforms":[` +
		`{"op":"copy","name":"old","to":"中 文+"},` +
		`{"op":"copy","name":"a b","to":"c d"},` +
		`{"op":"remove","name":"old"}]`
	if !strings.Contains(doc, wantSequence) {
		t.Fatalf("copy rules not preserved verbatim and in order:\n%s", doc)
	}
	if strings.Contains(doc, `"op":"copy","name":"old","to":"中 文+","value"`) {
		t.Fatalf("copy must not carry a value field:\n%s", doc)
	}

	// Resolving the same request before and after the save gives the same
	// routeId and upstreamURL: old is copied onto the encoded Chinese name
	// and then removed, "a b" (matched as a+b) is copied onto "c d".
	target := "/p?old=%2f+&a+b=1&keep=%41"
	after, _ := roundTripResolve(t, cfg, "GET", target)
	want := "http://h.internal/base/p?%E4%B8%AD%20%E6%96%87%2B=%2f+&a+b=1&c%20d=1&keep=%41"
	if after.UpstreamURL != want {
		t.Fatalf("upstreamURL = %q, want %q", after.UpstreamURL, want)
	}
}

