# Real mutation: copies appended at the end instead of after each source
python3 - <<'EOF'
s = open('contractsentinel/query.go').read()
old = """	encodedTo := encodeQueryComponent(to)
	out := make([]queryItem, 0, len(items))
	for _, it := range items {
		out = append(out, it)
		if !matchesName(it, name) {
			continue
		}
		frag := it.raw
		if j := strings.IndexByte(frag, '='); j >= 0 {
			// Keep the '=' and everything after it byte for byte.
			frag = encodedTo + frag[j:]
		} else {
			frag = encodedTo
		}
		out = append(out, queryItem{name: to, raw: frag})
	}
	return out"""
new = """	encodedTo := encodeQueryComponent(to)
	out := make([]queryItem, 0, len(items))
	var tail []queryItem
	for _, it := range items {
		out = append(out, it)
		if !matchesName(it, name) {
			continue
		}
		frag := it.raw
		if j := strings.IndexByte(frag, '='); j >= 0 {
			frag = encodedTo + frag[j:]
		} else {
			frag = encodedTo
		}
		tail = append(tail, queryItem{name: to, raw: frag})
	}
	return append(out, tail...)"""
assert old in s
open('contractsentinel/query.go','w').write(s.replace(old, new))
EOF
go test -run 'TestQueryTransformCopyComplexSeparatorName' ./contractsentinel/ 2>&1 | tail -3
cp /tmp/query.go.bak contractsentinel/query.go
go test ./... 2>&1 | tail -3 && gofmt -l contractsentinel/ && echo "gofmt clean"
